#include <stdio.h>
#include <stdlib.h>

int sum_record(long long *out) {
    int n;
    scanf("%d", &n);
    if (n < 1 || n > 100) {
        for (int i = 0; i < n; i++) {
            int skip;
            scanf("%d", &skip);
        }
        return -1;
    }
    int *values = malloc((size_t)n * sizeof *values);
    if (values == NULL) {
        return -1;
    }
    int negative = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
        if (values[i] < 0) {
            negative = 1;
        }
    }
    if (negative) {
        return -1;
    }
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += values[i];
    }
    free(values);
    *out = sum;
    return 0;
}

int main(void) {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        long long sum;
        if (sum_record(&sum) == 0) {
            printf("%lld\n", sum);
        } else {
            printf("invalid\n");
        }
    }
    return 0;
}

