#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Team {
    char *name;
    char **members;
    int count;
};

char *copy_text(const char *s) {
    char *c = malloc(strlen(s) + 1);
    if (c != NULL) {
        strcpy(c, s);
    }
    return c;
}

struct Team *team_read(void) {
    char buffer[32];
    int count;
    if (scanf("%31s %d", buffer, &count) != 2) {
        return NULL;
    }
    struct Team *t = calloc(1, sizeof *t);
    if (t == NULL) {
        return NULL;
    }
    t->name = copy_text(buffer);
    t->members = calloc((size_t)count, sizeof *t->members);
    for (int i = 0; i < count; i++) {
        scanf("%31s", buffer);
        t->members[i] = copy_text(buffer);
        t->count++;
    }
    return t;
}

void team_destroy(struct Team *t) {
    free(t);
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        struct Team *t = team_read();
        if (t == NULL) {
            return 1;
        }
        printf("%s:", t->name);
        for (int k = 0; k < t->count; k++) {
            printf(" %s", t->members[k]);
        }
        printf("\n");
        team_destroy(t);
    }
    return 0;
}

