#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int k;
    scanf("%d", &k);
    char *log[50] = {NULL};
    int pos = 0, evicted = 0;
    char buffer[32];
    while (scanf("%31s", buffer) == 1) {
        char *copy = malloc(strlen(buffer) + 1);
        if (copy == NULL) {
            break;
        }
        strcpy(copy, buffer);
        if (log[pos] != NULL) {
            evicted++;
        }
        free(log[pos]);
        log[pos] = copy;
        pos = (pos + 1) % k;
    }
    printf("%d\n", evicted);
    for (int i = 0; i < k; i++) {
        int index = (pos + i) % k;
        if (log[index] != NULL) {
            printf("%s\n", log[index]);
        }
    }
    for (int i = 0; i < k; i++) {
        free(log[i]);
    }
    return 0;
}

